import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ChevronLeft, ChevronRight } from 'lucide-react';

const testimonials = [
  {
    quote: "Frontier didn't just build our platform; they fundamentally improved our product strategy. Their engineering quality and attention to design detail are unmatched.",
    name: "Sarah Jenkins",
    role: "CTO, Nexus Financial",
    company: "Nexus"
  },
  {
    quote: "The technical architecture they implemented scaled effortlessly when we hit viral growth. Finding a team that understands both complex backend systems and premium UI is rare.",
    name: "Marcus Chen",
    role: "Founder, Aura Health",
    company: "Aura"
  },
  {
    quote: "Working with Frontier feels like having an elite in-house product team. Their transparency, speed, and standard of excellence transformed how we operate.",
    name: "Elena Rodriguez",
    role: "VP of Product, LogisTech",
    company: "LogisTech"
  }
];

const TestimonialsSection = () => {
  const [currentIndex, setCurrentIndex] = useState(0);

  const next = () => setCurrentIndex((prev) => (prev + 1) % testimonials.length);
  const prev = () => setCurrentIndex((prev) => (prev - 1 + testimonials.length) % testimonials.length);

  return (
    <section className="py-32 bg-[#090A0C] border-y border-border overflow-hidden">
      <div className="px-page max-w-5xl mx-auto text-center relative">
        <div className="text-accent-lime/20 font-serif text-[12rem] absolute top-[-80px] left-1/2 -translate-x-1/2 pointer-events-none select-none">"</div>

        <div className="min-h-[300px] flex flex-col justify-center relative z-10">
          <AnimatePresence mode="wait">
            <motion.div
              key={currentIndex}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -20 }}
              transition={{ duration: 0.5, ease: "easeOut" }}
            >
              <h3 className="font-serif italic text-3xl md:text-5xl leading-tight md:leading-tight mb-12 text-white">
                {testimonials[currentIndex].quote}
              </h3>

              <div>
                <div className="font-display font-bold text-lg">{testimonials[currentIndex].name}</div>
                <div className="text-secondary-text text-sm mt-1">{testimonials[currentIndex].role}</div>
              </div>
            </motion.div>
          </AnimatePresence>
        </div>

        <div className="flex items-center justify-center gap-6 mt-12">
          <button onClick={prev} className="w-12 h-12 rounded-full border border-border flex items-center justify-center hover:bg-white hover:text-dark-text transition-all">
            <ChevronLeft size={20} />
          </button>
          <div className="flex gap-2">
            {testimonials.map((_, i) => (
              <div key={i} className={`w-2 h-2 rounded-full transition-all duration-300 ${i === currentIndex ? 'bg-accent-lime w-6' : 'bg-border'}`} />
            ))}
          </div>
          <button onClick={next} className="w-12 h-12 rounded-full border border-border flex items-center justify-center hover:bg-white hover:text-dark-text transition-all">
            <ChevronRight size={20} />
          </button>
        </div>
      </div>
    </section>
  );
};

export default TestimonialsSection;
