import React, { useRef, useState, useEffect } from 'react';
import { motion, useAnimation } from 'framer-motion';

export const PremiumButton = ({ 
  children, 
  text, 
  className = '', 
  variant = 'lime', 
  ...props 
}: any) => {
  const buttonRef = useRef<HTMLButtonElement>(null);
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });
  const [isHovered, setIsHovered] = useState(false);
  const controls = useAnimation();

  // Match the site's color scheme
  const baseBg = variant === 'lime' ? 'bg-accent-lime' : 'bg-white';
  const hoverBg = variant === 'lime' ? '#000000' : '#090A0C';
  const baseText = 'text-black';
  const hoverText = variant === 'lime' ? 'group-hover:text-accent-lime' : 'group-hover:text-white';
  const hoverGlow = variant === 'lime' ? 'hover:shadow-[0_0_40px_rgba(214,255,79,0.4)]' : 'hover:shadow-[0_0_40px_rgba(255,255,255,0.3)]';

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!buttonRef.current) return;
    const rect = buttonRef.current.getBoundingClientRect();
    setMousePos({
      x: e.clientX - rect.left,
      y: e.clientY - rect.top,
    });
  };

  useEffect(() => {
    if (isHovered) {
      controls.start({
        scale: 1,
        transition: { duration: 0.5, ease: [0.16, 1, 0.3, 1] }
      });
    } else {
      controls.start({
        scale: 0,
        transition: { duration: 0.5, ease: [0.16, 1, 0.3, 1] }
      });
    }
  }, [isHovered, controls]);

  return (
    <button 
      ref={buttonRef}
      className={`group relative overflow-hidden flex items-center justify-center rounded-full transition-all duration-500 active:scale-95 ${baseBg} ${hoverGlow} ${className}`}
      onMouseMove={handleMouseMove}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      {...props}
    >
      {/* 
        Creative Cursor-Tracking Fill:
        A circle that exactly tracks the mouse and expands to fill the button on hover. 
      */}
      <motion.div 
        className="absolute z-0 pointer-events-none rounded-full"
        style={{
          width: '150%',
          paddingBottom: '150%', // Make it a perfect square
          left: mousePos.x,
          top: mousePos.y,
          x: '-50%',
          y: '-50%',
          backgroundColor: hoverBg,
        }}
        initial={{ scale: 0 }}
        animate={controls}
      />

      {/* Content Wrapper */}
      <span className={`relative z-10 flex items-center justify-center transition-colors duration-500 font-bold ${baseText} ${hoverText}`}>
        {text ? (
          <span className="font-mono tracking-[0.2em]">{text}</span>
        ) : (
          children
        )}
      </span>
    </button>
  );
};
